import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CuR1irRm.js";var i=JSON.parse(`{"title":"Notopia Edge","description":"","frontmatter":{"title":"Notopia Edge"},"headers":[],"relativePath":"deploy/k8s/notopia-edge.md","filePath":"deploy/k8s/notopia-edge.md"}`),a={name:`deploy/k8s/notopia-edge.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794061796000`},[...i[0]||=[e(`<h1 id="notopia-edge" tabindex="-1">notopia-edge <a class="header-anchor" href="#notopia-edge" aria-label="Permalink to “notopia-edge”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Name</th><th>Version</th></tr></thead><tbody><tr><td>file://../notopia-common-chart</td><td>notopia-common-chart</td><td>0.1.0</td></tr></tbody></table><h2 id="security-and-deployment" tabindex="-1">Security and deployment <a class="header-anchor" href="#security-and-deployment" aria-label="Permalink to “Security and deployment”">​</a></h2><p><strong>Security blocker:</strong> the chart does not establish a portable, non-bypassable identity-header boundary. Do not deploy or expose it until the operator has independently implemented and verified that boundary. Helm rendering/install/upgrade fails by default. After verification, set <code>security.externalBoundaryAcknowledged=true</code>; this is an operator assertion, not a control or evidence of security. A failed upgrade does not remove or secure an already-running release.</p><p>Replace the nonfunctional example JWT issuer and JWKS URI. Configure <code>frontRoute.parentRefs</code> and both <code>frontRoute.trustedNamespace</code> and <code>frontRoute.trustedGateway</code> for the gateway that strips all five identity headers. The chart creates a NetworkPolicy selecting the managed gateway&#39;s pods; by default it denies all ingress and, when configured, permits only pods labeled for that front gateway in that namespace. Existing gateways (<code>gateway.enabled=false</code>) are unsupported. <code>gateway.listenerPort</code> controls both the listener and front backend port.</p><p><strong>Required external controls:</strong> all traffic reaching the edge, including public paths and requests with absent JWT claims, must have the five client-supplied identity headers removed before trusted claims are set; no alternate front route may reach the edge without that removal. Prevent direct access to the edge service, pod IPs, host ports, load balancer and all other entry points. Restrict who can create or modify routes, pods, labels, gateways and network policies, including in the trusted namespace; a matching pod label is not authenticated identity. Ensure downstream services cannot be reached directly with spoofed identity headers. Use enforceable platform controls, such as a verified authenticated proxy-to-proxy boundary and centrally controlled routing; the precise mechanism is deployment-specific.</p><p><strong>NetworkPolicy is defense in depth, not a security proof.</strong> Enforcement depends on the CNI, selected pod labels, traffic path, host-network and node behavior. Policies are additive and another policy can widen access. A different route on the same front gateway or another pod with the same label may bypass the intended filter. Cluster and network administrators must verify these controls and their continuing operation; privileged operators can bypass them.</p><p>The billing admin group is mandatory; custom group paths are also excluded from the general JWT allow rule. Public and protected paths must not overlap. Path wildcards are supported only at the end; percent escapes, dot segments and repeated slashes are rejected. Header claim mappings are fixed to the stripped identity header contract.</p><p>When Istio is disabled, the NetworkPolicy remains, but Gateway API objects alone do not authenticate or authorize requests. Supply an external non-bypassable JWT verification and authorization layer that strips all five identity headers, sets trusted identity claims including <code>groups_json</code>, and enforces the public, authenticated and billing admin group rules. After independently verifying that layer, also set <code>security.externalIdentityLayerAcknowledged=true</code>. The chart cannot verify that this layer exists or that a non-Istio gateway implementation uses the expected pod labels.</p><p>Before exposure and after configuration or infrastructure changes, test direct edge access, an alternate front route, a spoofed-label pod, and all five forged headers with anonymous requests and tokens with missing claims. Test ordinary and admin users against admin paths, and repeat with Istio disabled when applicable. These checks require a representative cluster and do not follow from successful Helm rendering or acknowledgement.</p><h2 id="values" tabindex="-1">Values <a class="header-anchor" href="#values" aria-label="Permalink to “Values”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>frontRoute.enabled</td><td>bool</td><td><code>true</code></td><td>Create a route from the front gateway</td></tr><tr><td>frontRoute.hostnames</td><td>list</td><td><code>[]</code></td><td>Route hostnames</td></tr><tr><td>frontRoute.parentRefs</td><td>list</td><td><code>[]</code></td><td>Parent gateway references</td></tr><tr><td>frontRoute.trustedGateway</td><td>string</td><td><code>&quot;&quot;</code></td><td>Gateway API name of the only front gateway allowed to reach the edge</td></tr><tr><td>frontRoute.trustedNamespace</td><td>string</td><td><code>&quot;&quot;</code></td><td>Namespace of the only front gateway allowed to reach the edge</td></tr><tr><td>fullnameOverride</td><td>string</td><td><code>&quot;&quot;</code></td><td>Override the full release name</td></tr><tr><td>gateway.annotations</td><td>object</td><td><code>{}</code></td><td>Gateway annotations</td></tr><tr><td>gateway.className</td><td>string</td><td><code>&quot;istio&quot;</code></td><td>GatewayClass name</td></tr><tr><td>gateway.enabled</td><td>bool</td><td><code>true</code></td><td>Create the managed gateway; disabling is unsupported</td></tr><tr><td>gateway.hostname</td><td>string</td><td><code>&quot;&quot;</code></td><td>Listener hostname, empty for all hosts</td></tr><tr><td>gateway.listenerPort</td><td>int</td><td><code>80</code></td><td>Listener port</td></tr><tr><td>istio.adminGroup</td><td>string</td><td><code>&quot;admin&quot;</code></td><td>Group required for billing administration</td></tr><tr><td>istio.enabled</td><td>bool</td><td><code>true</code></td><td>Enable Istio authentication and authorization</td></tr><tr><td>istio.groupRules</td><td>list</td><td><code>[]</code></td><td>Additional group-protected paths and permitted groups</td></tr><tr><td>istio.jwt.issuer</td><td>string</td><td><code>&quot;https://auth.example.invalid/&quot;</code></td><td>JWT issuer; replace the nonfunctional example before deployment</td></tr><tr><td>istio.jwt.jwksUri</td><td>string</td><td><code>&quot;https://auth.example.invalid/jwks&quot;</code></td><td>JWKS endpoint; replace the nonfunctional example before deployment</td></tr><tr><td>istio.publicRules</td><td>list</td><td><code>[]</code></td><td>Additional public rules; paths must not overlap protected group paths</td></tr><tr><td>istio.telemetry.accessLogProviders</td><td>list</td><td><code>[]</code></td><td>Access logging provider names</td></tr><tr><td>istio.telemetry.enabled</td><td>bool</td><td><code>false</code></td><td>Enable Istio telemetry</td></tr><tr><td>istio.telemetry.randomSamplingPercentage</td><td>int</td><td><code>100</code></td><td>Trace sampling percentage</td></tr><tr><td>istio.telemetry.tracingProviders</td><td>list</td><td><code>[]</code></td><td>Tracing provider names</td></tr><tr><td>nameOverride</td><td>string</td><td><code>&quot;&quot;</code></td><td>Override the chart name</td></tr><tr><td>notopia-common-chart</td><td>object</td><td><code>{&quot;global&quot;:{}}</code></td><td>Common library configuration</td></tr><tr><td>security.externalBoundaryAcknowledged</td><td>bool</td><td><code>false</code></td><td>Operator acknowledges an externally enforced non-bypassable identity-header boundary</td></tr><tr><td>security.externalIdentityLayerAcknowledged</td><td>bool</td><td><code>false</code></td><td>Operator acknowledges an external JWT, header, and authorization layer when Istio is disabled</td></tr></tbody></table><hr><p>Autogenerated from chart metadata using <a href="https://github.com/norwoodj/helm-docs/releases/v1.14.2" target="_blank" rel="noreferrer">helm-docs v1.14.2</a></p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};